const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });

  console.log('Navigating to localhost:3000...');
  await page.goto('http://localhost:3000', { waitUntil: 'networkidle', timeout: 30000 });

  // Wait a bit for any dynamic content to render
  await page.waitForTimeout(3000);

  console.log('Page title:', await page.title());
  console.log('Page URL:', page.url());

  // Screenshot 1: Full page
  await page.screenshot({ 
    path: '/workspace/nia-universal/qa/task-list-fix-verification.png',
    fullPage: false 
  });
  console.log('Screenshot 1 saved: task-list-fix-verification.png');

  // Try to find task list / ActiveJobs widget
  const selectors = [
    '[class*=\"ActiveJobs\"]',
    '[class*=\"active-jobs\"]',
    '[class*=\"task-list\"]',
    '[class*=\"TaskList\"]',
    '[class*=\"job\"]',
    '[data-testid*=\"task\"]',
    '[data-testid*=\"job\"]',
  ];

  let found = null;
  for (const sel of selectors) {
    const el = await page.\$(sel);
    if (el) {
      found = { selector: sel, element: el };
      console.log('Found element with selector:', sel);
      break;
    }
  }

  if (found) {
    // Screenshot 2: Close-up of task area
    await found.element.screenshot({
      path: '/workspace/nia-universal/qa/task-card-closeup.png'
    });
    console.log('Screenshot 2 saved: task-card-closeup.png');
  } else {
    console.log('No specific task list selector found. Taking viewport screenshot as fallback.');
    // Log what elements are on the page for debugging
    const bodyHTML = await page.evaluate(() => {
      const classes = new Set();
      document.querySelectorAll('[class]').forEach(el => {
        el.className.split(' ').forEach(c => { if (c) classes.add(c); });
      });
      return Array.from(classes).filter(c => 
        /task|job|active|widget|panel|list|card/i.test(c)
      ).join(', ');
    });
    console.log('Relevant classes found:', bodyHTML || '(none)');

    // Take a second screenshot of just the main content area
    const main = await page.\$('main') || await page.\$('#__next') || await page.\$('body');
    if (main) {
      await main.screenshot({
        path: '/workspace/nia-universal/qa/task-card-closeup.png'
      });
      console.log('Screenshot 2 (fallback) saved: task-card-closeup.png');
    }
  }

  await browser.close();
  console.log('Done.');
})().catch(err => { console.error(err.message); process.exit(1); });
