  await page.click('button[type=\"submit\"], button:has-text(\"Sign In\")');

  // Wait for redirect after login
  await page.waitForTimeout(8000);

  console.log('Page title:', await page.title());
  console.log('Page URL:', page.url());

  // Screenshot 1: Full viewport showing task list
  await page.screenshot({ 
    path: '/workspace/nia-universal/qa/task-list-fix-verification.png',
    fullPage: false 
  });
  console.log('Screenshot 1 saved: task-list-fix-verification.png');

  // Find task-related elements
  const selectors = [
    '[class*=\"ActiveJobs\"]', '[class*=\"active-jobs\"]',
    '[class*=\"task-list\"]', '[class*=\"TaskList\"]',
    '[class*=\"task\"]', '[class*=\"Task\"]',
    '[class*=\"card\"]', '[class*=\"Card\"]',
    '[class*=\"sidebar\"]', '[class*=\"Sidebar\"]',
    '[class*=\"panel\"]', '[class*=\"Panel\"]',
    '[data-testid*=\"task\"]', '[data-testid*=\"job\"]',
  ];

  let found = null;
  let foundSel = '';
  for (const sel of selectors) {
    try {
      const els = await page.\$\$(sel);
      if (els.length > 0) {
        console.log('Found', els.length, 'element(s) with:', sel);
        if (!found) { found = els[0]; foundSel = sel; }
      }
    } catch(e) {}
  }

  if (found) {
    try {
      await found.screenshot({
        path: '/workspace/nia-universal/qa/task-card-closeup.png'
      });
      console.log('Screenshot 2 saved: task-card-closeup.png (selector:', foundSel, ')');
    } catch(e) {
      console.log('Could not screenshot element:', e.message);
    }
  } else {
    console.log('No task-specific selectors found, taking main content fallback');
    const main = await page.\$('main') || await page.\$('#__next') || await page.\$('body');
    if (main) {
      await main.screenshot({
        path: '/workspace/nia-universal/qa/task-card-closeup.png'
      });
      console.log('Screenshot 2 (fallback) saved');
    }
  }

  await browser.close();
  console.log('Done.');
})().catch(err => { console.error(err.message); process.exit(1); });
